import hashlib
from database import UserDatabase
from email_service import EmailService

class UserRegistration:
    def __init__(self):
        self.db = UserDatabase()
        self.email_service = EmailService()

    def validate_email(self, email):
        email_regex = r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'
        if re.match(email_regex, email) is None:
            return False
        return True

    def check_password_strength(self, password):
        # Assuming password strength is at least 8 characters long, contains a digit, a lowercase letter, and an uppercase letter
        if len(password) < 8:
            return False
        if not re.search("[a-z]", password):
            return False
        if not re.search("[A-Z]", password):
            return False
        if not re.search("[0-9]", password):
            return False
        return True

    def validate_username(self, username):
        # Assuming username is available
        if self.db.get_user(username) is not None:
            return False
        return True

    def register_user(self, username, email, password, preferences):
        if not self.validate_email(email):
            return "Invalid email format"
        if not self.check_password_strength(password):
            return "Weak password"
        if not self.validate_username(username):
            return "Username not available"

        hashed_password = hashlib.sha256(password.encode()).hexdigest()
        self.db.create_user(username, hashed_password, preferences)
