    def upload_file(self, file_path, new_name=None):
        if not os.path.exists(file_path):
            raise Exception(f"File {file_path} does not exist")

        if new_name is None:
            new_name = os.path.basename(file_path)
        new_path = os.path.join(self.base_dir, new_name)

        shutil.copy2(file_path, new_path)

        return new_name

    def retrieve_file(self, file_name, destination_path):
        file_path = os.path.join(self.base_dir, file_name)

        if not os.path.exists(file_path):
            raise Exception(f"File {file_path} does not exist")

        shutil.copy2(file_path, destination_path)

    def version_file(self, file_name):
        file_path = os.path.join(self.base_dir, file_name)

        if not os.path.exists(file_path):
            raise Exception(f"File {file_path} does not exist")

        file_hash = hashlib.md5(open(file_path, 'rb').read()).hexdigest()

        return file_hash

    def share_file(self, file_name, share_with):
        file_path = os.path.join(self.base_dir, file_name)

        if not os.path.exists(file_path):
            raise Exception(f"File {file_path} does not exist")

        os.chown(file_path, share_with.uid, share_with.gid)
        os.chmod(file_path, share_with.permissions)

    def schedule_cleanup(self, cleanup_interval):
        while True:
            for file_name in os.listdir(self.base_dir):
                file_path = os.path.join(self.base_dir, file_name)

                if os.path.isfile(file_path) and os.path.getmtime(file_path) < time.time() - cleanup_interval:
                    os.remove(file_path)

            time.sleep(cleanup_interval)

